const test=require('node:test');
const assert=require('node:assert/strict');
const {scryptSync}=require('node:crypto');
const {create,verify}=require('../accounts/service.cjs');
test('binary salt, exact UTF8 and independent digest',()=>{
  const salt=Buffer.from('00ff800102030405060708090a0b0c0d','hex');
  const password='密钥é';
  const digest=scryptSync(Buffer.from(password,'utf8'),salt,32,{N:1024,r:8,p:1}).toString('hex');
  const expected=['s1',salt.toString('hex'),digest].join('$');
  assert.equal(create(password,salt),expected);
  assert.equal(verify(password,expected),true);
  assert.equal(verify('wrong',expected),false);
  assert.equal(verify('密钥e\u0301',expected),false);
  assert.equal(salt.toString('hex'),'00ff800102030405060708090a0b0c0d');
});
test('malformed record and create salt',()=>{
  const valid=create('x',Buffer.alloc(16));
  for(const record of [null,17,'','s2'+valid.slice(2),valid+'$extra',valid+'\n',valid+'\r',valid+'\r\n',valid.slice(0,-1),valid.toUpperCase(),valid.replace('s1$','s1$zz')]) {
    assert.equal(verify('x',record),false);
  }
  for(const salt of [Buffer.alloc(15),'a'.repeat(16),new Uint8Array(16)]) assert.throws(()=>create('x',salt),TypeError);
});

