exports.parse=record=>{
  if(typeof record!=='string' || !/^s1\$[0-9a-f]{32}\$[0-9a-f]{64}$/.test(record) || record.length!==100) return null;
  const parts=record.split('$');
  return {salt:Buffer.from(parts[1],'hex'),digest:Buffer.from(parts[2],'hex')};
};
exports.format=(salt,digest)=>['s1',salt.toString('hex'),digest.toString('hex')].join('$');

