const {timingSafeEqual}=require('node:crypto');
const {parse,format}=require('./codec.cjs');
const {derive}=require('./kdf.cjs');
exports.create=(password,salt)=>{
  if(!Buffer.isBuffer(salt)||salt.length!==16) throw new TypeError('salt must be 16 bytes');
  return format(salt,derive(password,salt));
};
exports.verify=(password,record)=>{
  const parsed=parse(record);
  if(!parsed) return false;
  return timingSafeEqual(derive(password,parsed.salt),parsed.digest);
};

